namespace sv_da11d0a5f6684a08a8a214881b7cbe4f.Services;

/// <summary>
/// Scoped service that holds shared warehouse state for a single user circuit.
/// Components subscribe to change events to stay synchronized without parent-child relationships.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";
    private int _lowStockAlertCount;

    public string SelectedWarehouseId => _selectedWarehouseId;
    public int LowStockAlertCount => _lowStockAlertCount;

    public event Action? OnWarehouseChanged;
    public event Action? OnAlertCountChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A - Downtown"),
        ("WH-002", "Warehouse B - Airport"),
        ("WH-003", "Warehouse C - Harbor"),
        ("WH-004", "Warehouse D - Industrial Park")
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public void UpdateAlertCount(int count)
    {
        if (_lowStockAlertCount == count) return;
        _lowStockAlertCount = count;
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

namespace sv_da11d0a5f6684a08a8a214881b7cbe4f.Services;

/// <summary>
/// Simulates a database query for low-stock item counts per warehouse.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database query
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label text-muted mb-0 small">Current Warehouse</label>
    <select class="form-select form-select-sm" value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<span class="badge @BadgeClass rounded-pill ms-2">@WarehouseState.LowStockAlertCount</span>

@code {
    private string BadgeClass => WarehouseState.LowStockAlertCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnAlertCountChanged += OnStateChanged;
        WarehouseState.OnWarehouseChanged += OnStateChanged;
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnAlertCountChanged -= OnStateChanged;
        WarehouseState.OnWarehouseChanged -= OnStateChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h3>Warehouse Dashboard</h3>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Selected Warehouse</h5>
                <p class="card-text fs-5 fw-bold">@CurrentWarehouseName</p>
                <p class="card-text text-muted small">ID: @WarehouseState.SelectedWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card @AlertCardClass">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 fw-bold">@WarehouseState.LowStockAlertCount</p>
                <p class="card-text small">Items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Polling Status</h5>
                <p class="card-text">
                    @if (_isPolling)
                    {
                        <span class="badge bg-success">● Active</span>
                        <br /><small class="text-muted">Refreshing every 10s</small>
                    }
                    else
                    {
                        <span class="badge bg-secondary">● Stopped</span>
                    }
                </p>
                @if (_lastPollTime.HasValue)
                {
                    <p class="card-text small text-muted">Last poll: @_lastPollTime.Value.ToString("HH:mm:ss")</p>
                }
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <h5>Activity Log</h5>
    <div class="border rounded p-3" style="max-height: 250px; overflow-y: auto;">
        @if (_activityLog.Count == 0)
        {
            <p class="text-muted">Waiting for poll data...</p>
        }
        @foreach (var entry in _activityLog.AsEnumerable().Reverse())
        {
            <div class="small mb-1">
                <span class="text-muted">[@entry.Time.ToString("HH:mm:ss")]</span>
                @entry.Message
            </div>
        }
    </div>
</div>

@code {
    private CancellationTokenSource? _pollCts;
    private bool _isPolling;
    private DateTime? _lastPollTime;
    private readonly List<(DateTime Time, string Message)> _activityLog = new();

    private string CurrentWarehouseName =>
        Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.SelectedWarehouseId).Name
        ?? "Unknown";

    private string AlertCardClass => WarehouseState.LowStockAlertCount switch
    {
        0 => "border-success",
        <= 5 => "border-warning",
        _ => "border-danger"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += OnWarehouseChanged;
        WarehouseState.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPolling();
        }
    }

    private async Task StartPolling()
    {
        _pollCts = new CancellationTokenSource();
        _isPolling = true;
        StateHasChanged();

        _ = PollLoop(_pollCts.Token);
    }

    private async Task PollLoop(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
                _lastPollTime = DateTime.Now;

                // Update the shared state — this fires OnAlertCountChanged for ALL subscribers
                WarehouseState.UpdateAlertCount(count);

                await InvokeAsync(StateHasChanged);
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    private void OnWarehouseChanged()
    {
        _activityLog.Add((DateTime.Now, $"Switched to {CurrentWarehouseName}"));
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertCountChanged()
    {
        _activityLog.Add((DateTime.Now,
            $"Alert count updated: {WarehouseState.LowStockAlertCount} low-stock items at {CurrentWarehouseName}"));
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _isPolling = false;
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        WarehouseState.OnWarehouseChanged -= OnWarehouseChanged;
        WarehouseState.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

