namespace sv_da11d0a5f6684a08a8a214881b7cbe4f.Services;

/// <summary>
/// Scoped service that holds shared warehouse state for a single user circuit.
/// Components subscribe to change events to stay synchronized without parent-child relationships.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";
    private int _lowStockAlertCount;

    public string SelectedWarehouseId => _selectedWarehouseId;
    public int LowStockAlertCount => _lowStockAlertCount;

    public event Action? OnWarehouseChanged;
    public event Action? OnAlertCountChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A - Downtown"),
        ("WH-002", "Warehouse B - Airport"),
        ("WH-003", "Warehouse C - Harbor"),
        ("WH-004", "Warehouse D - Industrial Park")
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public void UpdateAlertCount(int count)
    {
        if (_lowStockAlertCount == count) return;
        _lowStockAlertCount = count;
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

